# ── Terminal colors (matching site/landing/index.html palette) ───────────────

def _supports_color() -> bool:
    if os.environ.get("NO_COLOR"):
        return False
    if os.environ.get("FORCE_COLOR"):
        return True
    if not hasattr(sys.stdout, "fileno"):
        return False
    try:
        import shutil as _shutil
        return _shutil.isatty(sys.stdout.fileno())
    except Exception:
        return False

_C = _supports_color()

def _c(code: str, text: str) -> str:
    return f"\x1b[{code}m{text}\x1b[0m" if _C else text

def cyan(text: str)     -> str: return _c("38;2;6;182;212", text)
def violet(text: str)   -> str: return _c("38;2;139;92;246", text)
def light_cyan(text: str) -> str: return _c("38;2;34;211;238", text)
def dim(text: str)      -> str: return _c("38;2;138;149;158", text)
def text(text: str)     -> str: return _c("38;2;228;232;236", text)

ROOT = Path(__file__).resolve().parents[2]
MARKER = "Generated by .github/scripts/compile_docs.py. Edit the Markdown sources instead.\n"


