# ── Markdown helpers ─────────────────────────────────────────────────────────

def plain(token: Token) -> str:
    """Text used in heading IDs, navigation, and search, without HTML markup."""
    if token.children:
        return "".join(plain(child) for child in token.children)
    return token.content if token.type not in {"html_inline", "html_block"} else ""


def slug(text: str) -> str:
    return re.sub(r"[^\w\- ]", "", text.lower()).replace(" ", "-") or "section"


def code_highlight(code: str, language: str, _attrs: str) -> str:
    lang_class = f' class="language-{escape(language.split(",")[0])}"'
    try:
        lexer = get_lexer_by_name(language.split(",")[0])
    except ClassNotFound:
        return f"<pre><code{lang_class}>{escape(code)}</code></pre>"
    rendered = highlight(code, lexer, HtmlFormatter(nowrap=True))
    # Wrap in <pre><code> with language class (Pygments returns just the inner content)
    return f"<pre><code{lang_class}>{rendered}</code></pre>"


def parser() -> markdown_it.MarkdownIt:
    return markdown_it.MarkdownIt("js-default", {
        "html": True,
        "highlight": code_highlight,
    })


# ── Frontmatter ──────────────────────────────────────────────────────────────

_YAML_RE = re.compile(r"^---\s*\n(.*?)\n^---\s*$", re.DOTALL | re.MULTILINE)

def parse_frontmatter(source: str) -> tuple[dict[str, str], str]:
    """Return (frontmatter_dict, body_without_frontmatter)."""
    m = _YAML_RE.match(source)
    if not m:
        return {}, source
    fm: dict[str, str] = {}
    for line in m.group(1).splitlines():
        if ":" in line:
            key, _, val = line.partition(":")
            fm[key.strip()] = val.strip().strip('"').strip("'")
    return fm, source[m.end():]


# ── Page reading ─────────────────────────────────────────────────────────────

@dataclass
class Page:
    source: Path
    output: Path
    title: str
    description: str = ""
    tokens: list[Token] = field(default_factory=list)
    headings: list[tuple[int, str, str]] = field(default_factory=list)


def read_pages(source: Path, md: markdown_it.MarkdownIt, version: str) -> list[Page]:
    pages = []
    outputs: set[Path] = set()
    for path in sorted(source.rglob("*.md")):
        if not path.resolve().is_relative_to(source):
            raise ValueError(f"Document escapes source directory: {path}")
        relative = path.relative_to(source)
        output = relative.with_name("index.html") if path.name == "README.md" else relative.with_suffix(".html")
        if output in outputs:
            raise ValueError(f"Duplicate HTML destination: {output}")
        outputs.add(output)

        raw = path.read_text(encoding="utf-8")
        fm, body = parse_frontmatter(raw)

        # Replace VitePress template variables
        body = re.sub(r"\{\{\s*\$frontmatter\.foreBlocksVersion\s*\}\}", version, body)

        # Replace [[toc]] markers with generated TOC HTML
        toc_html = _generate_toc(md, body)
        body = body.replace("[[toc]]", toc_html)

        tokens = md.parse(body)
        used: set[str] = set()
        headings = []
        title = fm.get("title", path.stem.replace("-", " ").capitalize())
        description = fm.get("description", "")
        for i, token in enumerate(tokens):
            if token.type != "heading_open":
                continue
            text = plain(tokens[i + 1])
            base = slug(text)
            anchor = base
            suffix = 0
            while anchor in used:
                suffix += 1
                anchor = f"{base}-{suffix}"
            used.add(anchor)
            token.attrSet("id", anchor)
            headings.append((int(token.tag[1:]), text, anchor))
            if token.tag == "h1" and not any(level == 1 for level, _, _ in headings[:-1]):
                title = text
        pages.append(Page(path.resolve(), output, title, description, tokens, headings))
    return pages


def _generate_toc(md: markdown_it.MarkdownIt, body: str) -> str:
    """Generate a table of contents from the document's headings."""
    tokens = md.parse(body)
    headings = []
    for i, token in enumerate(tokens):
        if token.type != "heading_open":
            continue
        text = plain(tokens[i + 1])
        base = slug(text)
        anchor = base
        suffix = 0
        while any(h[2] == anchor for h in headings):
            suffix += 1
            anchor = f"{base}-{suffix}"
        level = int(token.tag[1:])
        if level in (2, 3):
            headings.append((level, text, anchor))
    if not headings:
        return ""
    items = []
    for level, title, anchor in headings:
        indent = "  " * (level - 2)
        items.append(f'{indent}<a href="#{anchor}">{escape(title)}</a>\n')
    return '<nav class="fb-toc" aria-label="Table of contents">\n' + "".join(items) + "</nav>\n"


# ── Link rewriting ───────────────────────────────────────────────────────────

def relative_url(destination: Path, current: Path) -> str:
    # With <base href="/docs/"> all relative URLs resolve from /docs/
    # so we can use the destination path directly regardless of depth.
    return quote(destination.as_posix(), safe="/.-_")


def posixpath_relpath(path: str, start: str) -> str:
    """Pure-Python posixpath.relpath (avoids os.path platform dependency)."""
    path_parts = [p for p in path.split("/") if p]
    start_parts = [p for p in start.split("/") if p]
    common = 0
    for a, b in zip(path_parts, start_parts):
        if a == b:
            common += 1
        else:
            break
    up = len(start_parts) - common
    down = path_parts[common:]
    parts = [".."] * up + down
    return "/".join(parts) or "."


# ── Mermaid conversion ───────────────────────────────────────────────────────

_MERMAID_RE = re.compile(
    r'<pre><code class="language-mermaid">(.*?)</code></pre>',
    re.DOTALL,
)

def _convert_mermaid(html: str) -> str:
    """Convert ```mermaid code blocks to <div class="mermaid"> for client-side rendering."""
    def repl(m: re.Match) -> str:
        source = m.group(1).strip()
        encoded = quote(source, safe="")
        return f'<div class="mermaid" data-source="{encoded}"></div>'
    return _MERMAID_RE.sub(repl, html)


def rewrite_link(url: str, page: Page, pages: dict[Path, Page], root: Path,
                 repository: str, assets: dict[Path, Path], image: bool = False) -> str:
    parts = urlsplit(url)
    if parts.scheme or parts.netloc:
        return url
    # Strip trailing slash so "getting-started/" resolves to the file, not a directory
    clean_path = unquote(parts.path).rstrip("/") if parts.path else ""
    raw_target = (page.source.parent / clean_path).resolve() if clean_path else page.source
    # VitePress-style links may omit .md extension — try adding it
    target = raw_target
    if not target.exists():
        md_target = raw_target.with_suffix(raw_target.suffix + ".md") if raw_target.suffix else raw_target.with_name(raw_target.name + ".md")
        if md_target.is_file():
            target = md_target
    linked_page = pages.get(target)
    if linked_page:
        if parts.fragment and unquote(parts.fragment) not in {h[2] for h in linked_page.headings}:
            raise ValueError(f"{page.source}: missing heading in {url!r}")
        path = relative_url(linked_page.output, page.output) if parts.path else ""
        return urlunsplit(("", "", path, parts.query, parts.fragment))
    if not target.exists() or not target.is_relative_to(root):
        raise ValueError(f"{page.source}: missing or out-of-repository link {url!r}")
    repo_path = target.relative_to(root)
    if image:
        if not target.is_file():
            raise ValueError(f"{page.source}: image is not a file: {url!r}")
        destination = Path("_assets") / repo_path
        assets[destination] = target
        return urlunsplit(("", "", relative_url(destination, page.output), parts.query, parts.fragment))
    kind = "tree" if target.is_dir() else "blob"
    path = f"{repository}/{kind}/main/{quote(repo_path.as_posix(), safe='/')}"
    return path + ("?" + parts.query if parts.query else "") + ("#" + parts.fragment if parts.fragment else "")


def rewrite_tokens(page: Page, pages: dict[Path, Page], root: Path,
                   repository: str, assets: dict[Path, Path]) -> None:
    def visit(tokens: list[Token]) -> None:
        for token in tokens:
            attribute = "href" if token.type == "link_open" else "src" if token.type == "image" else None
            if attribute:
                url = token.attrGet(attribute)
                if url is not None:
                    token.attrSet(attribute, rewrite_link(url, page, pages, root, repository, assets, token.type == "image"))
            # Handle raw HTML links (html_inline/html_block tokens from markdown with html: True)
            if token.type in ("html_inline", "html_block"):
                token.content = re.sub(
                    r'href="([^"]*?)"',
                    lambda m: 'href="' + rewrite_link(m.group(1), page, pages, root, repository, assets) + '"',
                    token.content,
                )
            if token.children:
                visit(token.children)
    visit(page.tokens)


# ── Search entries ───────────────────────────────────────────────────────────

def search_entries(page: Page) -> list[dict[str, str]]:
    records = []
    text_parts: list[str] = []
    heading = page.title
    anchor = ""
    def flush() -> None:
        if text_parts:
            records.append({
                "title": page.title,
                "heading": heading,
                "url": page.output.as_posix() + ("#" + anchor if anchor else ""),
                "text": " ".join(text_parts),
            })
    for i, token in enumerate(page.tokens):
        if token.type == "heading_open":
            flush()
            text_parts = []
            heading = plain(page.tokens[i + 1])
            anchor = token.attrGet("id") or ""
        elif token.type in {"inline", "fence", "code_block"}:
            text_parts.append(plain(token))
    flush()
    return records


# ── Page rendering ───────────────────────────────────────────────────────────

def render_page(page: Page, pages: list[Page], body_html: str, repository: str, base_url: str) -> str:
    def href(path: str) -> str:
        # With <base href="/docs/"> all relative URLs resolve from /docs/
        # so we just need to produce the path as-is (no ../ needed).
        # Sidebar links like "/overview" → strip leading / and append .html.
        clean = path.lstrip("/")
        if not clean:  # root link "" or "/"
            return escape(clean, quote=True)
        # Only append .html for paths without an extension (sidebar nav links)
        if "." not in clean.split("/")[-1] and not clean.endswith("/"):
            clean += ".html"
        return escape(clean, quote=True)

    docs_root = posixpath.relpath(".", page.output.parent.as_posix()) + "/"
    home = posixpath.relpath("..", page.output.parent.as_posix()) + "/"

    # Sidebar navigation
    nav_items = []
    for group in SIDEBAR:
        items_html = "".join(
            f'<a href="{href(p["link"])}"'
            + (' aria-current="page"' if page.output.as_posix().lstrip("/") == p["link"].lstrip("/") else "")
            + f">{escape(p['text'])}</a>"
            for p in group["items"]
        )
        collapse_attr = ' class="collapsed"' if group.get("collapsed") else ""
        nav_items.append(
            f'<details open{collapse_attr}><summary>{escape(group["text"])}</summary><nav aria-label="{escape(group["text"])}">{items_html}</nav></details>'
        )
    navigation = "\n".join(nav_items)

    # Table of contents (right sidebar)
    toc = "".join(
        f'<a class="toc-level-{level}" href="#{escape(anchor)}">{escape(title)}</a>'
        for level, title, anchor in page.headings if level in {2, 3}
    )

    # Prev/Next
    index = pages.index(page)
    previous = pages[index - 1] if index else None
    following = pages[index + 1] if index + 1 < len(pages) else None
    adjacent = "".join(
        f'<a href="{href(p.output.as_posix())}"><small>{direction}</small>{escape(p.title)} <span aria-hidden="true">↗</span></a>'
        for p, direction in [(previous, "Previous guide"), (following, "Next guide")] if p
    )

    canonical = escape(base_url.rstrip("/") + "/docs/" + page.output.as_posix(), quote=True)
    edit_url = repository + "/blob/main/" + quote(page.source.relative_to(ROOT).as_posix(), safe="/") if page.source.is_relative_to(ROOT) else repository
    description = page.description or " ".join(plain(t) for t in page.tokens if t.type == "inline")[:180]

    return f'''<!doctype html>
<html lang="en">
<head>
<base href="/docs/">
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<meta name="description" content="{escape(description, quote=True)}">
<meta name="theme-color" content="#111318">
<title>{escape(page.title)} — foreBlocks docs</title>
<link rel="canonical" href="{canonical}">
<link rel="icon" href="{href('_static/logo.svg')}" type="image/svg+xml">
<link rel="stylesheet" href="{href('_static/site.css')}">
<link rel="stylesheet" href="{href('_static/docs.css')}">
<link rel="stylesheet" href="{href('_static/syntax.css')}">
<script src="{href('_static/app.js')}" defer></script>
<script src="{href('_static/docs.js')}" defer></script>
<script src="https://cdn.jsdelivr.net/npm/mermaid@11/dist/mermaid.min.js" defer></script>
</head>
<body class="landing-dark docs-body" data-docs-root="{escape(docs_root)}">
<a class="skip-link" href="#content">Skip to content</a>
<header class="site-header docs-header"><a class="brand" href="{escape(home)}"><img src="{href('_static/logo.svg')}" width="32" height="40" alt="">foreBlocks <span class="version"></span></a>
<nav aria-label="Main"><a href="{escape(home)}">Home</a><a href="{href('index.html')}" aria-current="true">Documentation</a><a href="{escape(repository)}">GitHub ↗</a></nav></header>
<div class="docs-layout">
<aside class="docs-sidebar">
<details class="guide-menu" open><summary>Documentation</summary><nav aria-label="Guides">{navigation}</nav></details>
<a class="source-link" href="{escape(edit_url)}">View Markdown source ↗</a>
</aside>
<main id="content" class="doc-main" tabindex="-1">
<div class="doc-toolbar"><span class="eyebrow">foreBlocks / DOCUMENTATION</span><form class="doc-search" role="search" action="{href('index.html')}" method="get"><label for="docs-search">Search guides</label><input id="docs-search" type="search" name="q" placeholder="Search guides…" autocomplete="off" aria-controls="search-results"><span id="search-status" class="sr-only" role="status"></span></form></div>
<section id="search-results" class="search-results" aria-label="Search results" hidden></section>
<noscript><p class="notice">Browse the guides with the navigation. Search needs JavaScript.</p></noscript>
<article class="prose">{body_html}</article>
<nav class="page-turn" aria-label="Adjacent guides">{adjacent}</nav>
<footer class="doc-footer">foreBlocks · Modular time-series forecasting for PyTorch · <a href="{escape(repository)}/blob/main/LICENSE">MIT license</a></footer>
</main>
<aside class="doc-toc"><nav aria-label="On this page"><p class="eyebrow">ON THIS PAGE</p>{toc}</nav></aside>
</div>
</body></html>'''


# ── Build ────────────────────────────────────────────────────────────────────

def build(source: Path, output: Path, root: Path = ROOT,
          repository: str = "https://github.com/lseman/foreblocks",
          base_url: str = "https://foreblocks.laioseman.com/",
          version: str = "0.0.0") -> int:
    source, output, root = source.resolve(), output.resolve(), root.resolve()
    if source == output or source in output.parents or output in source.parents:
        raise ValueError("Source and output directories must be separate, not nested.")
    if output.exists() and any(output.iterdir()):
        marker = output / ".generated-docs"
        if not marker.is_file() or marker.read_text() != MARKER:
            raise ValueError(f"Refusing to replace non-generated directory: {output}")

    md = parser()
    pages = read_pages(source, md, version)
    lookup = {p.source: p for p in pages}
    assets: dict[Path, Path] = {}
    search = [entry for page in pages for entry in search_entries(page)]

    for page in pages:
        rewrite_tokens(page, lookup, root, repository.rstrip("/"), assets)

    rendered = []
    for page in pages:
        body_html = md.renderer.render(page.tokens, md.options, {})
        # Convert ```mermaid ...``` blocks to <div class="mermaid"> for client-side rendering
        body_html = _convert_mermaid(body_html)
        rendered.append((page, render_page(page, pages, body_html, repository.rstrip("/"), base_url)))

    output.parent.mkdir(parents=True, exist_ok=True)
    with tempfile.TemporaryDirectory(prefix=".docs-build-", dir=output.parent) as temporary:
        stage = Path(temporary) / "docs"
        static = stage / "_static"
        static.mkdir(parents=True)

        # Copy shared static assets from landing page
        landing_static = ROOT / "site" / "landing"
        for name in ("logo.svg",):
            src = landing_static / name
            if src.exists():
                shutil.copy2(src, static / name)

        # Generate syntax CSS
        (static / "syntax.css").write_text(
            HtmlFormatter(style=LandingDarkStyle).get_style_defs(".prose pre"),
            encoding="utf-8",
        )

        # Copy docs CSS and JS from VitePress theme area
        vs = ROOT / "docs" / ".vitepress"
        if (vs / "config.js").exists():
            # Copy the extra.css as site.css
            css_src = ROOT / "docs" / "stylesheets" / "extra.css"
            if css_src.exists():
                shutil.copy2(css_src, static / "site.css")

        # Write generated CSS for docs layout (minimal, matching landing palette)
        (static / "docs.css").write_text(_DOCS_CSS, encoding="utf-8")
        (static / "app.js").write_text(_APP_JS, encoding="utf-8")
        (static / "docs.js").write_text(_DOCS_JS, encoding="utf-8")

        for page, document in rendered:
            destination = stage / page.output
            destination.parent.mkdir(parents=True, exist_ok=True)
            destination.write_text(document + "\n", encoding="utf-8")

        for destination, original in assets.items():
            target = stage / destination
            target.parent.mkdir(parents=True, exist_ok=True)
            shutil.copy2(original, target)

        (stage / "search-index.json").write_text(
            json.dumps(search, ensure_ascii=False), encoding="utf-8"
        )
        (stage / ".generated-docs").write_text(MARKER, encoding="utf-8")

        # Atomic replace: rename old → backup, then stage → output
        old = Path(temporary) / "previous"
        if output.exists():
            output.rename(old)
        try:
            stage.rename(output)
        except OSError:
            if old.exists():
                old.rename(output)
            raise

    return len(pages)


