_APP_JS = r"""// foreBlocks docs — shared utilities
(function() {
  'use strict';
  // Smooth scroll for anchor links
  document.addEventListener('click', function(e) {
    var a = e.target.closest('a[href^="#"]');
    if (a) {
      var id = a.getAttribute('href').slice(1);
      var el = document.getElementById(id);
      if (el) { e.preventDefault(); el.scrollIntoView({ behavior: 'smooth' }); }
    }
  });
})();
"""

_DOCS_JS = r"""// foreBlocks docs — mermaid + search
(function() {
  'use strict';

  // ── Mermaid rendering ───────────────────────────────────────────────
  function renderMermaid() {
    if (typeof mermaid === 'undefined') return;
    var diagrams = document.querySelectorAll('.prose .mermaid');
    if (!diagrams.length) return;
    mermaid.initialize({
      startOnLoad: false, securityLevel: 'loose', theme: 'base',
      themeVariables: {
        darkMode: true, background: '#191c24', primaryColor: '#292438',
        primaryTextColor: '#dce0e9', primaryBorderColor: '#a78bfa',
        lineColor: '#a5adbd', secondaryColor: '#20352f', tertiaryColor: '#202b38',
        edgeLabelBackground: '#191c24', fontFamily: 'Inter, system-ui, sans-serif'
      }
    });
    mermaid.run({ nodes: Array.from(diagrams) }).catch(function() {});
  }

  // ── Search ──────────────────────────────────────────────────────────
  var input = document.getElementById('docs-search');
  var status = document.getElementById('search-status');
  if (!input) return;
  var resultsEl = document.getElementById('search-results');
  var indexUrl = (document.body.dataset.docsRoot || '') + 'search-index.json';

  function debounce(fn, ms) {
    var t; return function() { clearTimeout(t); t = setTimeout(fn, ms); };
  }

  async function search(q) {
    if (!q || q.length < 2) { resultsEl.hidden = true; status.textContent = ''; return; }
    try {
      var resp = await fetch(indexUrl);
      if (!resp.ok) throw new Error('fetch failed');
      var data = await resp.json();
      var terms = q.toLowerCase().split(/\s+/);
      var scored = [];
      for (var i = 0; i < data.length; i++) {
        var item = data[i];
        var text = (item.text + ' ' + item.heading + ' ' + item.title).toLowerCase();
        var score = 0;
        for (var j = 0; j < terms.length; j++) {
          if (text.indexOf(terms[j]) !== -1) score += 1;
        }
        if (score > 0) scored.push({ score: score, item: item });
      }
      scored.sort(function(a, b) { return b.score - a.score; });
      var html = '';
      for (var k = 0; k < Math.min(scored.length, 10); k++) {
        var s = scored[k];
        html += '<div class="search-result-item"><a href="' + s.item.url + '">' + s.item.heading + ' <span style="color:var(--fb-dim)">' + s.item.title + '</span></a></div>';
      }
      resultsEl.innerHTML = html;
      resultsEl.hidden = scored.length === 0;
      status.textContent = scored.length + ' result' + (scored.length !== 1 ? 's' : '') + ' found';
    } catch (err) {
      status.textContent = 'Search unavailable';
    }
  }

  input.addEventListener('input', debounce(function() { search(input.value.trim()); }, 200));

  // Render mermaid diagrams after DOM is ready
  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', renderMermaid);
  } else {
    renderMermaid();
  }
})();
"""


# ── CLI ──────────────────────────────────────────────────────────────────────

def main() -> int:
    cli = argparse.ArgumentParser(description=__doc__)
    cli.add_argument("--source", type=Path, default=ROOT / "docs")
    cli.add_argument("--output", type=Path, default=ROOT / "site" / "docs")
    cli.add_argument("--repository-url", default="https://github.com/lseman/foreblocks")
    cli.add_argument("--base-url", default="https://foreblocks.laioseman.com/",
                     help="Public site URL, including its project prefix")
    cli.add_argument("--version", default=None, help="foreBlocks version (reads pyproject.toml if omitted)")
    args = cli.parse_args()

    # Read version from pyproject.toml if not provided
    version = args.version
    if not version:
        pyproject_text = (ROOT / "pyproject.toml").read_text(encoding="utf-8")
        m = re.search(r'^version\s*=\s*"([^"]+)"', pyproject_text, re.M)
        if not m:
            print("Could not find version in pyproject.toml", file=sys.stderr)
            return 1
        version = m.group(1)

    try:
        count = build(args.source, args.output, repository=args.repository_url,
                      base_url=args.base_url, version=version)
    except (OSError, ValueError) as error:
        print(f"Documentation build failed: {error}", file=sys.stderr)
        return 1

    # Terminal output with colors
    sep = "─" * 50
    print(f"\n  {'╔' + sep + '╗'}")
    print(f"  {'║' + text(' foreBlocks ') + cyan(version) + ' ' + dim('— compile_docs.py').ljust(37) + '║'}")
    print(f"  {'╚' + sep + '╝'}\n")
    print(f"  {violet('▸')} {text(f'Compiled {count} guides → ')}{cyan(str(args.output.relative_to(ROOT)))}\n")

    return 0


if __name__ == "__main__":
    raise SystemExit(main())
